import{_ as r,a0 as s,w as p,s as u,ao as i,I as o,x as e,a1 as n,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"開源賽車遊戲 StuntRally 的新的 2.3 版本看起來棒極了 | LCTT x X-CMD","titleTemplate":false,"description":"開源賽車遊戲 StuntRally 的新的 2.3 版本看起來棒極了 | LCTT (201405) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"開源賽車遊戲 StuntRally 的新的 2.3 版本看起來棒極了 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"開源賽車遊戲 StuntRally 的新的 2.3 版本看起來棒極了 | LCTT (201405) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201405/The New Open Source StuntRally 2.3 Racing Game Looks Great","title":"開源賽車遊戲 StuntRally 的新的 2.3 版本看起來棒極了","tag":"201405","desc":""},"relativePath":"201405/The New Open Source StuntRally 2.3 Racing Game Looks Great.md","filePath":"[post].md"}'),m={name:"201405/The New Open Source StuntRally 2.3 Racing Game Looks Great.md"};function d(S,t,f,T,R,y){const l=s("Link");return p(),u("div",null,[t[16]||(t[16]=i('<h1 id="開源賽車遊戲-stuntrally-的新的-2-3-版本看起來棒極了" tabindex="-1">開源賽車遊戲 StuntRally 的新的 2.3 版本看起來棒極了 <a class="header-anchor" href="#開源賽車遊戲-stuntrally-的新的-2-3-版本看起來棒極了" aria-label="Permalink to “開源賽車遊戲 StuntRally 的新的 2.3 版本看起來棒極了”">​</a></h1><p><img src="http://i1-news.softpedia-static.com/images/news2/The-new-Open-Source-StuntRally-2-3-Racing-Game-Looks-Great-441726-2.jpg" alt=""></p><p>StuntRally是一個有着多達150條特色賽道和大量汽車模型的免費賽車遊戲，它剛剛發佈了最新的2.3版本，新版本的畫質有了很大的提高。</p><p>該遊戲是建立在大量的開源技術上的，如Vdrift，bullet，OGRE，PagedGeometry和MyGUI，雖然在此僅僅舉了這幾個例子，但是這個遊戲絕對不是一個簡單的項目。 僅僅從他的特點描述中就能看出，StuntRally大概是在Linux平台上最有前景的開源街機賽車遊戲之一。</p><p>玩家可以從153條賽車軌道和24個關卡中感受到遊戲的魅力，並且這款遊戲超過四個小時的遊戲時間真是業界良心啊。 StuntRally特色功能有幽靈駕駛模式（在比賽中最接近你的賽車的視角），賽道幽靈車（每條賽道上都有一個綠色的幽靈記錄車），當然還有回放（保存你得駕駛記錄，並且你可以從其他的攝像頭視角觀看）。當然，遊戲中也有教程，錦標賽，挑戰賽以及多人比賽等。但是這些功能都僅僅只是表面的特點。</p><p>如果我們注意到這是一個免費的遊戲，僅僅是開發人員在業餘時所做的，Stuntrally的圖形效果就已經相當不錯了。遊戲中玩家需要設定八個的圖形參數，包裹地形的視差，三維映射，汽車和水中的倒影，水的折射，開花，運動模糊，SSAO，景深，日光和HDR。其中一些最新的功能將需要玩家重新購買一個新的顯卡才行。</p><p>除此之外，開發商還開發了賽道編輯器，允許用户實時編輯比賽道路和它們的參數，通過改變賽道的參數、調整地形，甚至修改自己的賽車，從而讓駕駛樂趣倍增。</p><p>這次的變更説明顯示，所有的賽道都被重新制作了，所有的紋理地形貼圖已經升級到1K像素，背景噪音目前也有了很多的變化，不再是單一的一種聲音，光線現在也有了多個照射路徑，更加真實，草的密度現在已經渲染到了一個極致，動態攝像機也已經添加，並且遊戲開始的燃料現在取決於軌道長度。</p><p>此外，用户現在可以選擇的地形紋理、草和植被模型窗口，地形編輯，現在按鍵比之前方便了很多，新版本的編輯器中有大量的修改，比如，圖層按鈕已被調換，賽道編輯器的起始位置也已經改變，圖層，草和植被按鈕上的已被更新，對地形和路面參數的表面標籤已被添加，等等。</p>',9)),o("p",null,[t[2]||(t[2]=e("關於StuntRally的這一新版本的更多詳情，可在",-1)),n(l,{href:"https://code.google.com/p/vdrift-ogre/wiki/VersionHistory"},{default:a(()=>[...t[0]||(t[0]=[e("公告",-1)])]),_:1}),t[3]||(t[3]=e("中找到。你現在可以從官方",-1)),n(l,{href:"http://sourceforge.net/projects/stuntrally/files/"},{default:a(()=>[...t[1]||(t[1]=[e("網站",-1)])]),_:1}),t[4]||(t[4]=e("下載StuntRally2.3。",-1))]),t[17]||(t[17]=o("hr",null,null,-1)),o("p",null,[t[6]||(t[6]=e("via: ",-1)),n(l,{href:"http://news.softpedia.com/news/The-new-Open-Source-StuntRally-2-3-Racing-Game-Looks-Great-441726.shtml"},{default:a(()=>[...t[5]||(t[5]=[e("http://news.softpedia.com/news/The-new-Open-Source-StuntRally-2-3-Racing-Game-Looks-Great-441726.shtml",-1)])]),_:1})]),o("p",null,[t[9]||(t[9]=e("譯者：",-1)),n(l,{href:"https://github.com/MikeCoder"},{default:a(()=>[...t[7]||(t[7]=[e("MikeCoder",-1)])]),_:1}),t[10]||(t[10]=e(" 校對：",-1)),n(l,{href:"https://github.com/wxy"},{default:a(()=>[...t[8]||(t[8]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[13]||(t[13]=e("本文由 ",-1)),n(l,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原創翻譯，",-1)),n(l,{href:"http://linux.cn/"},{default:a(()=>[...t[12]||(t[12]=[e("Linux中國",-1)])]),_:1}),t[15]||(t[15]=e(" 榮譽推出",-1))])])}const L=r(m,[["render",d]]);export{C as __pageData,L as default};
